	private static void Add( List<Mesh> meshes, Material material, float[] data, int[] indices )
	{
		var vertices = new Vertex[data.Length / 6];
		for ( var i = 0; i < vertices.Length; i++ )
		{
			var k = i * 6;
			vertices[i] = new Vertex( new Vector3( data[k], data[k+1], data[k+2] ), new Vector3( data[k+3], data[k+4], data[k+5] ), Vector3.Forward, new Vector4() );
		}
		var mesh = new Mesh( material );
		mesh.CreateVertexBuffer( vertices.Length, vertices );
		mesh.CreateIndexBuffer( indices.Length, indices );
		mesh.Bounds = new BBox( new Vector3( -20, -33, -5 ), new Vector3( 18, 33, 7 ) );
		meshes.Add( mesh );
	}
